// 分类验证 Schema
const CategorySchema = z.object({
  name: z.string().min(1, "名称不能为空").max(50, "名称不能超过50个字符"),
  nameEn: z.string().min(1, "英文名称不能为空").max(50, "英文名称不能超过50个字符"),
  slug: z
    .string()
    .min(1, "URL别名不能为空")
    .max(50, "URL别名不能超过50个字符")
    .regex(/^[a-z0-9-]+$/, "URL别名只能包含小写字母、数字和连字符"),
});

// 生成 slug
function generateSlug(name: string): string {
  return name
    .toLowerCase()
    .replace(/[\s_]+/g, "-")
    .replace(/[^\w\-]+/g, "")
    .replace(/--+/g, "-")
    .replace(/^-+/, "")
    .replace(/-+$/, "");
}

export function CategoryForm({ open, onClose, onSuccess, category }: CategoryFormProps) {
  const { success, error: showError } = useToast();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [formData, setFormData] = useState({
    name: "",
    nameEn: "",
    slug: "",
    icon: "" as string | null,
    visible: true,
  });
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [saving, setSaving] = useState(false);
  const [iconMode, setIconMode] = useState<"preset" | "custom">("preset");
  const [customIconError, setCustomIconError] = useState<string | null>(null);

  const isEdit = !!category;

  // 初始化表单数据
  useEffect(() => {
    if (category) {
      setFormData({
        name: category.name,
        nameEn: category.nameEn,
        slug: category.slug,
        icon: category.icon || null,
        visible: category.visible ?? true,
      });
      // 判断是否为自定义图标
      const isPreset = presetIcons.some((p) => p.svg === category.icon);
      setIconMode(isPreset || !category.icon ? "preset" : "custom");
    } else {
      setFormData({ name: "", nameEn: "", slug: "", icon: null, visible: true });
      setIconMode("preset");
    }
    setErrors({});
    setCustomIconError(null);
  }, [category, open]);

  // 自动生成 slug
  useEffect(() => {
    if (!isEdit && formData.nameEn && !formData.slug) {
      setFormData((prev) => ({
        ...prev,
        slug: generateSlug(prev.nameEn),
      }));
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [formData.nameEn, isEdit]);

  // 选择预设图标
  const selectIcon = (iconSvg: string) => {
    setFormData((prev) => ({
      ...prev,
      icon: prev.icon === iconSvg ? null : iconSvg,
    }));
  };

  // 处理 SVG 文件上传
  const handleSvgUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // 验证文件类型
    if (!file.type.includes("svg") && !file.name.endsWith(".svg")) {
      setCustomIconError("请上传 SVG 格式的文件");
      return;
    }

    // 验证文件大小 (最大 50KB)
    if (file.size > 50 * 1024) {
      setCustomIconError("SVG 文件大小不能超过 50KB");
      return;
    }

    try {
      const text = await file.text();

      // 简单验证是否为有效的 SVG
      if (!text.includes("<svg") || !text.includes("</svg>")) {
        setCustomIconError("无效的 SVG 文件");
        return;
      }

      // 清理 SVG：安全净化 + 样式标准化
      let cleanedSvg = sanitizeSvg(text);

      // 确保使用 currentColor 以支持颜色变化
      // 将 fill="xxx" 替换为 fill="currentColor"（除了 none 和 transparent）
      cleanedSvg = cleanedSvg.replace(
        /fill="(?!none|transparent|currentColor)[^"]*"/gi,
        'fill="currentColor"'
      );

      // 二次确认净化后仍包含 svg 标签
      if (!cleanedSvg.includes("<svg") || !cleanedSvg.includes("</svg>")) {
        setCustomIconError("上传的 SVG 文件无效或包含不安全内容");
        return;
      }

      setFormData((prev) => ({ ...prev, icon: cleanedSvg }));
      setCustomIconError(null);
    } catch {
      setCustomIconError("读取文件失败");
    }

    // 清空 input 以便可以重复选择同一文件
    e.target.value = "";
  };

  // 更新表单字段
  const updateField = (key: keyof typeof formData, value: string) => {
    setFormData((prev) => ({ ...prev, [key]: value }));
    if (errors[key]) {
      setErrors((prev) => {
        const next = { ...prev };
        delete next[key];
        return next;
      });
    }
  };

  // 验证表单
  const validateForm = (): boolean => {
    try {
      CategorySchema.parse(formData);
      setErrors({});
      return true;
    } catch (err) {
      if (err instanceof z.ZodError) {
        const fieldErrors: Record<string, string> = {};
        err.issues.forEach((e) => {
          if (e.path[0]) {
            fieldErrors[String(e.path[0])] = e.message;
          }
        });
        setErrors(fieldErrors);
      }
      return false;
    }
  };

  // 保存分类
  const handleSave = async () => {
    if (!validateForm()) {
      return;
    }

    setSaving(true);
    try {
      if (isEdit) {
        await apiPut(`/api/admin/categories/${category.id}`, formData);
      } else {
        await apiPost("/api/admin/categories", formData);
      }

      success(isEdit ? "分类已更新" : "分类已创建");
      onSuccess();
      onClose();
    } catch (err) {
      showError(err instanceof Error ? err.message : "保存失败");
    } finally {
      setSaving(false);
    }
  };

  return (
    <Modal open={open} onClose={onClose} title={isEdit ? "编辑分类" : "新增分类"} size="md">
      <div className="space-y-4">
        <Input
          label="分类名称（中文）"
          value={formData.name}
          onChange={(e) => updateField("name", e.target.value)}
          error={errors.name}
          placeholder="如：护肤精华"
          required
        />
        <Input
          label="分类名称（英文）"
          value={formData.nameEn}
          onChange={(e) => updateField("nameEn", e.target.value)}
          error={errors.nameEn}
          placeholder="如：Essence"
          required
        />
        <Input
          label="URL 别名"
          value={formData.slug}
          onChange={(e) => updateField("slug", e.target.value)}
          error={errors.slug}
          placeholder="自动生成，可修改"
          required
        />

        {/* 前台展示开关 */}
        <div className="flex items-center justify-between rounded-lg border border-gray-200 bg-gray-50 px-4 py-3">
          <div>
            <label className="text-sm font-medium text-gray-700">前台展示</label>
            <p className="text-xs text-gray-500">关闭后该分类不会在产品页显示</p>
          </div>
          <button
            type="button"
            onClick={() => setFormData((prev) => ({ ...prev, visible: !prev.visible }))}
            className={cn(
              "relative h-6 w-11 rounded-full transition-colors",
              formData.visible ? "bg-brand-primary" : "bg-gray-300"
            )}
          >
            <span
              className={cn(
                "absolute left-0.5 top-0.5 h-5 w-5 rounded-full bg-white shadow transition-transform",
                formData.visible && "translate-x-5"
              )}
            />
          </button>
        </div>

        {/* 图标选择器 */}
        <div>
          <label className="mb-2 block text-sm font-medium text-gray-700">
            分类图标（用于产品页分类栏）
          </label>

          {/* 切换标签 */}
          <div className="mb-3 flex rounded-lg border border-gray-200 bg-gray-50 p-1">
            <button
              type="button"
              onClick={() => setIconMode("preset")}
              className={cn(
                "flex-1 rounded-md px-3 py-1.5 text-sm font-medium transition-all",
                iconMode === "preset"
                  ? "bg-white text-brand-primary shadow-sm"
                  : "text-gray-500 hover:text-gray-700"
              )}
            >
              预设图标
            </button>
            <button
              type="button"
              onClick={() => setIconMode("custom")}
              className={cn(
                "flex-1 rounded-md px-3 py-1.5 text-sm font-medium transition-all",
                iconMode === "custom"
                  ? "bg-white text-brand-primary shadow-sm"
                  : "text-gray-500 hover:text-gray-700"
              )}
            >
              上传自定义
            </button>
          </div>

          {/* 预设图标网格 */}
          {iconMode === "preset" && (
            <div className="grid grid-cols-5 gap-2 rounded-lg border border-gray-200 bg-gray-50 p-3">
              {presetIcons.map((icon) => (
                <button
                  key={icon.id}
                  type="button"
                  onClick={() => selectIcon(icon.svg)}
                  className={cn(
                    "group relative flex flex-col items-center justify-center gap-1 rounded-lg border p-2 transition-all",
                    formData.icon === icon.svg
                      ? "border-brand-primary bg-brand-primary/10 ring-1 ring-brand-primary"
                      : "border-gray-200 bg-white hover:border-brand-primary/50 hover:bg-brand-primary/5"
                  )}
                  title={icon.name}
                >
                  <div
                    className={cn(
                      "h-8 w-8 transition-colors",
                      formData.icon === icon.svg
                        ? "text-brand-primary"
                        : "text-gray-500 group-hover:text-brand-primary"
                    )}
                    dangerouslySetInnerHTML={{ __html: sanitizeSvg(icon.svg) }}
                  />
                  <span className="text-[10px] text-gray-500">{icon.name}</span>
                </button>
              ))}
            </div>
          )}

          {/* 自定义上传 */}
          {iconMode === "custom" && (
            <div className="rounded-lg border border-gray-200 bg-gray-50 p-4">
              <input
                ref={fileInputRef}
                type="file"
                accept=".svg,image/svg+xml"
                className="hidden"
                onChange={handleSvgUpload}
              />

              {/* 已上传的自定义图标预览 */}
              {formData.icon && !presetIcons.some((p) => p.svg === formData.icon) ? (
                <div className="flex items-center gap-4">
                  <div className="flex h-16 w-16 items-center justify-center rounded-lg border-2 border-brand-primary bg-brand-primary/10 p-2">
                    <div
                      className="h-full w-full text-brand-primary"
                      dangerouslySetInnerHTML={{ __html: sanitizeSvg(formData.icon) }}
                    />
                  </div>
                  <div className="flex-1">
                    <p className="text-sm font-medium text-gray-700">已上传自定义图标</p>
                    <p className="text-xs text-gray-500">点击下方按钮更换图标</p>
                  </div>
                  <button
                    type="button"
                    onClick={() => setFormData((prev) => ({ ...prev, icon: null }))}
                    className="rounded-lg p-2 text-gray-400 hover:bg-gray-100 hover:text-red-500"
                    title="删除图标"
                  >
                    <X className="h-5 w-5" />
                  </button>
                </div>
              ) : (
                <div className="flex flex-col items-center justify-center py-4 text-center">
                  <Upload className="mb-2 h-8 w-8 text-gray-400" />
                  <p className="text-sm text-gray-600">上传 SVG 格式的图标文件</p>
                  <p className="mt-1 text-xs text-gray-400">建议尺寸 40x40，最大 50KB</p>
                </div>
              )}

              <Button
                type="button"
                variant="outline"
                size="sm"
                className="mt-3 w-full"
                leftIcon={<Upload className="h-4 w-4" />}
                onClick={() => fileInputRef.current?.click()}
              >
                {formData.icon && !presetIcons.some((p) => p.svg === formData.icon)
                  ? "更换图标"
                  : "选择 SVG 文件"}
              </Button>

              {customIconError && <p className="mt-2 text-xs text-red-500">{customIconError}</p>}

              <p className="mt-3 text-xs text-gray-400">
                提示：SVG 中的颜色填充会自动转换为 currentColor，以支持在产品页动态变色
              </p>
            </div>
          )}

          {formData.icon && (
            <button
              type="button"
              onClick={() => setFormData((prev) => ({ ...prev, icon: null }))}
              className="mt-2 text-xs text-gray-500 hover:text-red-500"
            >
              清除已选图标
            </button>
          )}
        </div>
      </div>

      <div className="mt-6 flex justify-end gap-3">
        <Button variant="outline" onClick={onClose}>
          取消
        </Button>
        <Button onClick={handleSave} loading={saving}>
          {isEdit ? "保存" : "创建"}
        </Button>
      </div>
    </Modal>
  );
}
